export const PlacementDriveStatusKeyToLabel = {
  'StatusKey0': 'Upcoming',
  'StatusKey1': 'Active',
  'StatusKey2': 'Completed',
  'StatusKey3': 'Cancelled'
} as const;
export type PlacementDriveStatusKey = keyof typeof PlacementDriveStatusKeyToLabel;

export interface PlacementDrive {
  /**
   * @displayName Placement Drive ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Company Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  companyName: string;
  /**
   * @displayName Application Deadline
   * @validationRule Required for create/update operations
   */
  applicationDeadline: string;
  /**
   * @displayName Company Logo
   */
  companyLogo?: string;
  /**
   * @displayName Description
   */
  description?: string;
  /**
   * @displayName Drive Date
   * @validationRule Required for create/update operations
   */
  driveDate: string;
  /**
   * @displayName Job Role
   * @validationRule Required for create/update operations
   */
  jobRole: string;
  /**
   * @displayName Location
   * @validationRule Required for create/update operations
   */
  location: string;
  /**
   * @displayName Openings
   * @validationRule Required for create/update operations
   */
  openings: number;
  /**
   * @displayName Package (LPA)
   * @validationRule Required for create/update operations
   */
  packageLPA: number;
  /**
   * @displayName Status
   * @validationRule Required for create/update operations
   */
  statusKey: PlacementDriveStatusKey;
}

export const _PlacementDrive = 'PlacementDrive' as const;
